import shlex
import re
from subprocess import Popen
from robot.api import logger
from ta5g_global_var import SIM_ENB_IP_WITH_MASK, UPLANE_IP_WITH_MASK
from ta5g_interface_tools import log_name


SIM_GNB_IP = '10.0.1.6'


class VmManagement(object):
    _templates = {
        "indexed_network_interface_name": "{if_name}{index}",
        "ip_address_with_modifiable_last_octet_and_mask": "{address_prefix}.{last_octet}/{mask}",
        "start_network_interface": "sudo ifconfig {if_name} {ip_with_mask} up",
        "stop_network_interface": "sudo ifconfig {if_name} down",
    }
    templates = {"start_netcat": "nc {options} {ip} -p {port}"}
    _netcat_process = None

    def turn_on_netcat(self, options, ip, port):
        """
        Turns on netcat in background.
        :param options: an extra parameters passed to netcat, for example -i 10
        :param ip: an ip
        :param port: a port

        :return: None
        """
        logger.console("Turning on NetCat")
        args_splited = shlex.split(VmManagement.templates["start_netcat"].format(options=options, ip=ip, port=port))
        self._netcat_process = Popen(args_splited)

    def turn_off_netcat(self):
        """
        Kills netcat's process.

        :return: None
        """
        logger.console("Turning off NetCat")
        self._netcat_process.kill()

    @classmethod
    def start_vm_ethernet_interface(cls, if_name, ip_with_mask):
        """
        Starts a vm ethernet interface
        :param if_name: an interface name
        :param ip_with_mask: an ip address with mask

        :return: None
        """
        command = cls._templates["start_network_interface"].format(if_name=if_name, ip_with_mask=ip_with_mask)

        cls._run_process_and_wait(command)

    @classmethod
    def stop_vm_ethernet_interface(cls, if_name, ip_with_mask):
        """
        Stops a vm ethernet interface
        :param if_name: an interface name
        :param ip_with_mask: an ip address with mask

        :return: None
        """
        command = cls._templates["stop_network_interface"].format(if_name=if_name)

        cls._run_process_and_wait(command)

    @classmethod
    @log_name(level="INFO")
    def start_default_simulated_SANSA_interfaces(cls):
        """
        Starts a default simulated interfaces which are required to reach OnAir in SA+NSA configuration.

        :return: None
        """
        cls.start_vm_ethernet_interface(if_name="eth3:MME_S1", ip_with_mask="10.0.1.131/24")
        cls.start_vm_ethernet_interface(if_name="eth3:SERVER", ip_with_mask="10.0.1.132/24")
        cls.start_vm_ethernet_interface(if_name="eth3:S1U", ip_with_mask="10.0.1.133/24")
        cls.start_vm_ethernet_interface(if_name="eth3:S11", ip_with_mask="10.0.1.134/24")
        cls.start_vm_ethernet_interface(if_name="eth3:X2U", ip_with_mask="10.0.1.135/24")
        cls.start_vm_ethernet_interface(if_name="eth3:ENB_S1", ip_with_mask="10.0.1.136/24")
        cls.start_vm_ethernet_interface(if_name="eth3:ENB_X2", ip_with_mask="10.0.1.137/24")

    @classmethod
    def start_default_simulated_enb_interface(cls):
        """
        Starts a default simulated enb interface with a name eth3:simeNB
        and an ip with mask defined in ta5g_global_variables

        :return: None
        """
        cls.start_vm_ethernet_interface("eth3:simeNB", SIM_ENB_IP_WITH_MASK)

    @classmethod
    def stop_default_simulated_enb_interface(cls):
        """
        Stops a default simulated enb interface.

        :return: None
        """
        cls.stop_vm_ethernet_interface("eth3:simeNB", SIM_ENB_IP_WITH_MASK)

    @classmethod
    def start_default_simulated_gnb_interface(cls, ip=SIM_GNB_IP):
        ip_with_mask = cls._concat_ip_with_mask(ip)
        cls.start_vm_ethernet_interface("eth3:simgNB", ip_with_mask)

    @classmethod
    def stop_default_simulated_gnb_interface(cls, ip=SIM_GNB_IP):
        ip_with_mask = cls._concat_ip_with_mask(ip)
        cls.stop_vm_ethernet_interface("eth3:simgNB", ip_with_mask)

    @classmethod
    def start_xn_and_ng_interfaces_for_second_gnb(cls):
        """
        Starts XN interface with a name eth3:xn and NG interface with a name eth3:ng

        :return: None
        """
        cls.start_vm_ethernet_interface(if_name="eth3:GNBSIM_XN", ip_with_mask="10.0.1.101/24")
        cls.start_vm_ethernet_interface(if_name="eth3:GNBSIM_NG", ip_with_mask="10.0.1.102/24")

    @classmethod
    def start_multiple_vm_ethernet_interfaces(cls, if_name, first_if_id, last_if_id, ipv4_address="10.0.1.3"):
        """
        Starts up multiple vm ethernet interfaces, starting from first_if_id to last_if_id inclusive,
        with a name indexed by an id and the last octet of the provided ip address replaced with an interface id.
        :param if_name: an interface name
        :param first_if_id: first interface index
        :param last_if_id: last interface index
        :param ipv4_address: a base ip address, last octet will be removed, 24 mask will be appended

        :return: None
        """
        interfaces = cls._prepare_interfaces_list(if_name, int(first_if_id), int(last_if_id), ipv4_address)

        for interface in interfaces:
            cls.start_vm_ethernet_interface(interface["if_name"], interface["ip_with_mask"])

    @classmethod
    def stop_multiple_vm_ethernet_interfaces(cls, if_name, first_if_id, last_if_id, ipv4_address="10.0.1.3"):
        """
        Starts a default simulated enb interface with a name eth3:simeNB
        and an ip with a mask defined in SIM_ENB_IP_WITH_MASK(ta_global_variables)"

        :return: None
        """
        interfaces = cls._prepare_interfaces_list(if_name, int(first_if_id), int(last_if_id), ipv4_address)

        for interface in interfaces:
            cls.stop_vm_ethernet_interface(interface["if_name"], interface["ip_with_mask"])

    @classmethod
    def start_multiple_vm_ethernet_interfaces_with_different_ips(cls, if_name_with_ip_list):
        """
        Starts multiple vm ethernet interfaces with different ip
        :param if_name_with_ip_list: an interface name and ip address with mask in list,
        possible to add multiple lists separated by comma e.g [eth3:gNB2_X2, 10.0.1.3/24], [eth3:gNB3_X2, 10.0.1.4/24]
        :return: None
        """
        pattern = re.compile(r'\[.*?]')
        list_of_interfaces = pattern.findall(if_name_with_ip_list)
        for interface in list_of_interfaces:
            interface = interface.strip("[]").split(",")
            command = cls._templates["start_network_interface"].format(if_name=interface[0], ip_with_mask=interface[1])
            cls._run_process_and_wait(command)

    @classmethod
    def stop_multiple_vm_ethernet_interfaces_with_different_ips(cls, if_name_with_ip_list):
        """
        Stops multiple vm ethernet interfaces with different ip
        :param if_name_with_ip_list: an interface name and ip address with mask in list,
        possible to add multiple lists separated by comma e.g [eth3:gNB2_X2, 10.0.1.3/24], [eth3:gNB3_X2, 10.0.1.4/24]
        :return: None
        """
        pattern = re.compile(r'\[.*?]')
        list_of_interfaces = pattern.findall(if_name_with_ip_list)
        for interface in list_of_interfaces:
            interface = interface.strip("[]").split(",")
            command = cls._templates["stop_network_interface"].format(if_name=interface[0], ip_with_mask=interface[1])
            cls._run_process_and_wait(command)

    @classmethod
    def start_uplane_tunnel(cls):
        """
        Starts Uplane Tunnel
        :return:
        """
        cls.start_vm_ethernet_interface("eth4:Uplane", UPLANE_IP_WITH_MASK)

    @classmethod
    def start_simulated_mme_interface(cls):
        """
        Starts Simulated Mme Interface
        :return:
        """
        cls.start_vm_ethernet_interface("eth2:simmme", SIM_ENB_IP_WITH_MASK)

    @classmethod
    def stop_simulated_mme_interface(cls):
        """
        Starts Simulated Mme Interface
        :return:
        """
        cls.stop_vm_ethernet_interface("eth2:simmme", SIM_ENB_IP_WITH_MASK)

    @staticmethod
    def _cut_off_last_octet_from_ipv4(ip):
        return ip.rsplit('.', 1)[0]

    @classmethod
    def _prepare_interfaces_list(cls, if_name, first_if_id, last_if_id, ipv4_address):
        interfaces = []
        address_prefix = cls._cut_off_last_octet_from_ipv4(ipv4_address)

        for i in range(first_if_id, last_if_id + 1):
            parsed_if_name = cls._templates["indexed_network_interface_name"].format(if_name=if_name, index=i)
            parsed_ip_with_mask = cls._templates["ip_address_with_modifiable_last_octet_and_mask"].format(
                address_prefix=address_prefix, last_octet=i, mask=24
            )
            interfaces.append({"if_name": parsed_if_name, "ip_with_mask": parsed_ip_with_mask})
        return interfaces

    @staticmethod
    def _run_process_and_wait(command):
        process = Popen(shlex.split(command))
        process.wait()

    @staticmethod
    def _concat_ip_with_mask(ip, mask=24):
        return '{}/{}'.format(ip, mask)
